//! Crisp raster icons with no external fonts or assets.
use crate::settings::DisplayMode;
#[derive(Debug, Clone)] pub struct IconPixels { pub width:u32, pub height:u32, pub rgba:Vec<u8> }
fn put(p:&mut IconPixels,x:i32,y:i32,c:[u8;4]) { if x>=0&&y>=0&&x<p.width as i32&&y<p.height as i32 {let i=((y as u32*p.width+x as u32)*4)as usize;p.rgba[i..i+4].copy_from_slice(&c);} }
fn rect(p:&mut IconPixels,x:i32,y:i32,w:i32,h:i32,c:[u8;4]){for yy in y..y+h{for xx in x..x+w{put(p,xx,yy,c)}}}
const FONT5:[[u8;7];11]=[[31,17,17,17,17,17,31],[4,12,4,4,4,4,14],[31,1,1,31,16,16,31],[31,1,1,15,1,1,31],[17,17,17,31,1,1,1],[31,16,16,31,1,1,31],[31,16,16,31,17,17,31],[31,1,2,4,8,8,8],[31,17,17,31,17,17,31],[31,17,17,31,1,1,31],[0,0,0,0,0,0,0]];
const FONT3:[[u8;5];10]=[[7,5,5,5,7],[2,6,2,2,7],[7,1,7,4,7],[7,1,7,1,7],[5,5,7,1,1],[7,4,7,1,7],[7,4,7,5,7],[7,1,2,2,2],[7,5,7,5,7],[7,5,7,1,7]];
fn digit(p:&mut IconPixels,d:u8,x:i32,y:i32,scale:i32,c:[u8;4]){for(row,bits)in FONT5[d as usize].iter().enumerate(){for col in 0..5{if bits&(1<<(4-col))!=0{rect(p,x+col*scale,y+row as i32*scale,scale,scale,c)}}}}
fn small_digit(p:&mut IconPixels,d:u8,x:i32,y:i32,c:[u8;4]){for(row,bits)in FONT3[d as usize].iter().enumerate(){for col in 0..3{if bits&(1<<(2-col))!=0{put(p,x+col,y+row as i32,c)}}}}
fn small_number(p:&mut IconPixels,text:&str,y:i32,c:[u8;4]){let width=text.len()as i32*4-1;let mut x=(p.width as i32-width)/2;for ch in text.bytes(){if ch.is_ascii_digit(){small_digit(p,ch-b'0',x,y,c);}else{rect(p,x+1,y,1,3,c);put(p,x+1,y+4,c);}x+=4;}}
pub fn make_icon(size:u32, mode:DisplayMode, percent:Option<u8>, low:u8)->IconPixels { let mut p=IconPixels{width:size,height:size,rgba:vec![0;(size*size*4)as usize]};let color=match percent{None=>[145,145,145,255],Some(v)if v<=low=>[220,55,55,255],Some(v)if v<=40=>[230,160,35,255],_=>[50,190,90,255]};let s=size as i32;let scale=(s/16).max(1); if mode!=DisplayMode::Number {let x=scale; let y=scale; let w=s-4*scale; let h=7*scale;let border=[235,235,235,255];rect(&mut p,x,y,w,h,[30,30,30,245]);rect(&mut p,x,y,w,scale,border);rect(&mut p,x,y,scale,h,border);rect(&mut p,x+w-scale,y,scale,h,border);rect(&mut p,x,y+h-scale,w,scale,border);rect(&mut p,x+w,y+2*scale,2*scale,3*scale,border);if let Some(v)=percent{let ix=x+2*scale;let iy=y+2*scale;let iw=w-4*scale;let ih=h-4*scale;rect(&mut p,ix,iy,(iw*v as i32)/100,ih,color);} }
if mode==DisplayMode::IconPercent {small_number(&mut p,&percent.map(|v|v.to_string()).unwrap_or_else(||"?".into()),10*scale,[245,245,245,255]);} else if mode==DisplayMode::Number {let text=percent.map(|v|v.to_string()).unwrap_or_else(||"?".into());let sc=if size<=16 {1}else{(s/24).max(1)};let tw=(text.len()as i32*6-1)*sc;let mut xx=(s-tw)/2;let yy=(s-7*sc)/2;for ch in text.bytes(){if ch.is_ascii_digit(){digit(&mut p,ch-b'0',xx,yy,sc,[245,245,245,255]);}else{rect(&mut p,xx+2*sc,yy,sc,4*sc,[245,245,245,255]);rect(&mut p,xx+2*sc,yy+6*sc,sc,sc,[245,245,245,255]);}xx+=6*sc;}}
p }
#[cfg(test)] mod tests {use super::*;#[test]fn icons_have_pixels(){for s in 16..65{for m in [DisplayMode::IconPercent,DisplayMode::Icon,DisplayMode::Number]{for v in [None,Some(0),Some(100)]{assert!(make_icon(s,m,v,20).rgba.iter().any(|x|*x!=0));}}}}#[test]fn one_hundred_fits(){let p=make_icon(16,DisplayMode::Number,Some(100),20);assert_eq!(p.width,16);}}
